<script lang="ts" module>
</script>

<script lang="ts">
	import { API, Constants } from "$lib";
	import { Button, buttonVariants } from "$lib/components/ui/button";
	import Carousel from "$lib/components/ui/Carousel.svelte";
	import { PersistentStore } from "$lib/hooks";
	import { prefs } from "$lib/stores";
	import { cn } from "$lib/Utils";
	import { ArrowRightIcon, ChevronUp } from "@lucide/svelte";
	import { onMount } from "svelte";
	import { HTTPError } from "$lib/HTTP";
	import { libraryIdentity, libraryViewKey, captureLibraryView } from "$localLibrary/library";
	import { captureNativeAuthority, nativeAuthority, sameNativeReadAuthority } from "$platform/mutation-authority";
	import { createSafeReadOwner } from "$platform/safe-read-owner";
	import { requireReadAcknowledgement, readFailure } from "$platform/mutation-feedback";
	import ErrorComponent from "./ErrorComponent.svelte";
	import LatestUpdatesGridEntry from "./LatestUpdatesGridEntry.svelte";
	import LatestUpdatesGridSkeleton from "./LatestUpdatesGridSkeleton.svelte";
	import MangaSearchEntryCard from "./MangaSearchEntryCard.svelte";
	import MangaSearchEntrySkeleton from "./MangaSearchEntrySkeleton.svelte";
	let feed = $state<MappedChapterFeedResponse>(), entries = $state<Chapter[]>([]), idMap = $state<Record<string, undefined>>({});
	let isMounted = $state(false), isLoading = $state(false), mountedLifecycle = $state(false), error = $state<Constants.Error.Error>();
	const isCollapsed = new PersistentStore("ivtnx7u8", false), reads = createSafeReadOwner();
	let pending = false, draining = false, observed = "";
	const query = () => { const q = new URLSearchParams(); prefs.applyMangaPreferences(q); prefs.applyChapterPreferences(q); q.delete("tagx"); q.delete("txmod"); q.set("limit", "10"); return q; };
	const queryKey = () => JSON.stringify([...query().entries()]);
	function queueUpdates() {
		if (!reads.isLive()) return;
		reads.invalidate(); pending = true; feed = undefined; entries = []; idMap = {}; error = undefined; isMounted = false;
		void Promise.resolve().then(drain);
	}
	async function drain() {
		if (draining || !reads.isLive()) return;
		draining = true; isLoading = true;
		try {
			while (pending && reads.isLive()) {
				pending = false;
				const view = captureLibraryView(), account = $libraryIdentity.mode === "account", authority = captureNativeAuthority(), key = queryKey();
				const intent = reads.capture(() => captureLibraryView() === view && queryKey() === key && (!account || sameNativeReadAuthority(authority)));
				try {
					const body = requireReadAcknowledgement(await API.MangaFollow.LatestUpdates(query()));
					if (!intent.alive()) { if (intent.current()) error = readFailure(new HTTPError(409, "The selected library or requested filters changed while loading. Retry the current updates.")); continue; }
					if (!Array.isArray(body.data)) throw new HTTPError(502, "The server returned an invalid personal update feed.");
					feed = body;
					for (const chapter of body.data) { const id = chapter.relationships.manga.id; if (!(id in idMap)) { idMap[id] = undefined; entries.push(chapter); } }
					entries = entries;
				} catch (cause) { if (intent.current()) error = intent.alive() ? readFailure(cause) : readFailure(new HTTPError(409, "The previous personal update request no longer belongs to this library. Retry the current updates.")); }
				finally { if (intent.current()) isMounted = true; }
			}
		} finally { draining = false; if (reads.isLive()) isLoading = false; }
	}
	onMount(() => { mountedLifecycle = true; });
	$effect.pre(() => {
		if (!mountedLifecycle || !reads.isLive()) return;
		const view = $libraryViewKey, mode = $libraryIdentity.mode, authority = $nativeAuthority, preferences = $prefs;
		const key = JSON.stringify([view, mode === "account" ? authority.epoch : null, queryKey()]);
		if (key === observed) return; observed = key; queueUpdates();
	});
</script>

{#if !isMounted || entries.length || error}
	<section>
		<header class="flex items-center gap-2" class:mb-3={!$isCollapsed}>
			<div class="flex w-0 flex-auto items-center gap-2">
				<h2 class="text-xl font-medium">My Updates</h2>
				<Button
					class="relative"
					type="button"
					variant="ghost"
					size="icon"
					onclick={() => ($isCollapsed = !$isCollapsed)}
				>
					<ChevronUp class={cn("size-6 transition-all", $isCollapsed && "-rotate-180")} />
				</Button>
			</div>
			<div class="flex shrink-0 items-center gap-2">
				<a class={buttonVariants({ variant: "ghost", size: "icon" })} href="/library/updates">
					<ArrowRightIcon class="size-6" />
				</a>
			</div>
		</header>
		<div class:hidden={$isCollapsed}>
			{#if error}
				<ErrorComponent {error} />
				<Button variant="outline" disabled={isLoading} onclick={queueUpdates}>Retry updates</Button>
			{:else if isMounted && entries.length}
				<Carousel slidesPerView={2} breakpoints={Constants.MangaSliderBreakpoints} spaceBetween={12}>
					{#each entries as chapter (chapter)}
						<article class="swiper-slide relative">
							<MangaSearchEntryCard manga={chapter.relationships.manga} isGrid />
							<LatestUpdatesGridEntry {chapter} />
						</article>
					{/each}
				</Carousel>
			{:else}
				<Carousel slidesPerView={2} breakpoints={Constants.MangaSliderBreakpoints} spaceBetween={12}>
					{#each Array.from({ length: 10 })}
						<article class="swiper-slide relative">
							<MangaSearchEntrySkeleton isGrid />
							<LatestUpdatesGridSkeleton />
						</article>
					{/each}
				</Carousel>
			{/if}
		</div>
	</section>
{/if}
